export function createAdminClientsUI({api,esc,openDialog,closeDialog,toast}){
 let active=false,epoch=0,clients=[],selected=null,search='',state='all';
 const money=n=>(Number(n||0)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
 const planLabel={essential:'Essencial',assisted:'Assistido'},statusLabel={active:'Ativo',offered:'Proposta enviada',accepted:'Aguardando pagamento',open:'Em aberto',pending:'Em conferência',paid:'Pago',canceled:'Cancelado',cancel_pending:'Cancelamento em análise'};
 const label={active:'Ativa',inactive:'Inativa',deleted:'Excluída do diretório'};
 const endpoint=org=>'/api/portal/admin-clients'+(org?'?org='+encodeURIComponent(org):'');
 const btn=(text,action,id)=>`<button class="p-button secondary" data-client-action="${action}" data-id="${esc(id)}">${text}</button>`;
 function page(){return '<section class="page-heading"><div><p class="overline">GESTÃO DE CLIENTES</p><h1>Uma visão completa de cada empresa.</h1><p>Cadastro, acesso, entregas e financeiro reunidos para a equipe.</p></div></section><div id="client-directory"></div>';}
 function paint(){const host=document.querySelector('#client-directory');if(!host||!active)return;const items=clients.filter(c=>(state==='all'?c.control.state!=='deleted':c.control.state===state)&&c.name.toLocaleLowerCase('pt-BR').includes(search));host.innerHTML=`<div class="client-toolbar"><label class="p-field">Buscar empresa<input id="client-search" type="search" value="${esc(search)}" placeholder="Nome da empresa"></label><label class="p-field">Situação<select id="client-state">${[['all','Ativas e inativas'],['active','Ativas'],['inactive','Inativas'],['deleted','Excluídas']].map(([k,v])=>`<option value="${k}" ${k===state?'selected':''}>${v}</option>`).join('')}</select></label><p>${items.length} empresa(s)</p></div><div class="admin-client-grid">${items.map(c=>`<article class="admin-box client-card"><div class="client-card-title"><span class="client-monogram" aria-hidden="true">${esc(c.name.slice(0,2).toUpperCase())}</span><div><h2>${esc(c.name)}</h2><span class="p-tag">${esc(label[c.control.state])}</span></div></div><p class="client-access">${c.control.grantActive?'Acesso liberado · '+(c.control.grant.purpose==='own'?'uso próprio':'teste'):c.subscription?'Plano '+esc(planLabel[c.subscription.plan]||c.subscription.plan)+' · '+esc(statusLabel[c.subscription.state]||c.subscription.state):'Sem plano contratado'}</p><div class="client-stats"><span><strong>${c.contents}</strong> conteúdos</span><span><strong>${c.consultations}</strong> serviços</span></div><div class="client-card-actions">${btn('Abrir empresa','open',c.id)}${btn('Editar cadastro','edit',c.id)}</div></article>`).join('')||'<p>Nenhuma empresa encontrada.</p>'}</div>`;}
 async function load(){const ticket=++epoch;try{const d=await api(endpoint());if(!active||ticket!==epoch)return;clients=d.clients;paint();}catch(e){if(active&&ticket===epoch)document.querySelector('#client-directory').textContent=e.message;}}
 async function open(id){const ticket=epoch,d=await api(endpoint(id));if(!active||ticket!==epoch)return;selected=d;detail('summary');}
 function detail(tab){const d=selected,c=d.company,k=d.control,id=c.id;const file=a=>`<a href="/api/portal/admin-client-files/${encodeURIComponent(a.id)}?org=${encodeURIComponent(id)}" target="_blank" rel="noopener">${esc(a.name)}</a>`;
 const sections={summary:`<div class="client-stats"><span>Recebido<strong>${money(d.finance.paid)}</strong></span><span>Em aberto<strong>${money(d.finance.open)}</strong></span><span>Conteúdos<strong>${d.contents.length}</strong></span></div><p>${d.members.map(m=>esc(m.name)+' · '+esc(m.email)).join('<br>')}</p><p>${esc(k.contact||'Contato adicional não informado.')}</p><p class="preserve-lines">${esc(k.notes||'Sem anotações internas.')}</p><div class="client-card-actions">${btn('Editar cadastro','edit',id)}${btn(k.state==='active'?'Inativar empresa':'Reativar empresa',k.state==='active'?'suspend':'activate',id)}${k.state!=='deleted'?btn('Excluir do diretório','delete',id):''}</div>`,access:`<h3>${k.grantActive?'Acesso administrativo liberado':'Acesso por contratação'}</h3><p>${k.grantActive?(k.grant.purpose==='own'?'Uso próprio, sem franquia interna.':'Teste, sem franquia interna.')+(k.grant.end?' Até '+new Date(k.grant.end).toLocaleDateString('pt-BR'): ' Sem data final.'):'Os planos pagos dependem do aceite e de um recebimento confirmado.'}</p><p>Liberações de teste ou uso próprio não geram cobrança, receita ou comprovante de pagamento.</p><div class="client-card-actions">${btn('Liberar teste / uso próprio','grant',id)}${k.grantActive?btn('Encerrar liberação','revoke',id):''}<a class="p-button primary" href="#/commerce?org=${encodeURIComponent(id)}">Contratar / ativar plano pago</a></div>`,finance:`<p>Recebido: <strong>${money(d.finance.paid)}</strong> · Em aberto: ${money(d.finance.open)}</p><a class="p-button primary" href="#/finance?org=${encodeURIComponent(id)}">Cobranças e confirmar recebimento</a>${d.finance.charges.map(r=>`<p>${esc(r.description)} · ${money(r.amountCents)} · ${esc(statusLabel[r.state]||r.state)}</p>`).join('')}`,contents:`<p>Consulta administrativa dos materiais. Conversas privadas não são abertas nesta área.</p>${d.contents.map(r=>`<article class="client-list-row"><strong>${esc(r.title||'Conteúdo')}</strong><span>${esc(r.format||'')} · ${esc(r.status||'')}</span>${r.assetId?file({id:r.assetId,name:'Ver material'}):''}</article>`).join('')||'<p>Nenhum conteúdo salvo.</p>'}`,documents:`<p>Arquivos da empresa. A consulta pela equipe fica registrada no histórico administrativo.</p>${d.documents.map(a=>`<article class="client-list-row">${file(a)}<span>${esc(a.mime)} · ${(a.size/1048576).toFixed(1)} MB</span></article>`).join('')||'<p>Nenhum documento.</p>'}`};
 openDialog(c.name,`<p class="overline">${esc(label[k.state])}</p><nav class="client-tabs" aria-label="Detalhes da empresa">${[['summary','Resumo'],['access','Acesso ao plano'],['finance','Financeiro'],['contents','Criações'],['documents','Documentos']].map(([key,name])=>`<button class="p-button ${key===tab?'primary':'secondary'}" data-client-tab="${key}">${name}</button>`).join('')}</nav><section class="client-detail">${sections[tab]}</section>`,true);}
 function form(action){const {company:c,control:k}=selected;let fields='';const input=(name,text,value='',type='text')=>`<label class="p-field">${text}<input name="${name}" type="${type}" value="${esc(value)}" required></label>`;
 if(action==='edit')fields=input('name','Empresa',c.name)+input('contact','Contato administrativo',k.contact||'').replace(' required','')+`<label class="p-field">Anotações internas<textarea name="notes" maxlength="2000">${esc(k.notes||'')}</textarea></label>`;
 if(action==='grant')fields='<label class="p-field">Finalidade<select name="purpose"><option value="test">Teste</option><option value="own">Empresa própria</option></select></label><label class="p-field">Último dia do acesso (obrigatório para teste, até 90 dias)<input name="end" type="date"></label><label class="checkline"><input name="confirmed" type="checkbox" required> Liberar criação sem franquia interna. O uso dos provedores continua sendo cobrado.</label>';
 if(action==='delete')fields='<p>A empresa será retirada do diretório e ficará sem novas execuções. Documentos, cobranças e histórico serão preservados. É possível reativá-la pelo filtro Excluídas.</p>'+input('confirmName','Digite o nome exato da empresa');
 if(action==='suspend')fields='<p>Novas gerações e execuções pendentes serão bloqueadas. Cobranças e histórico serão preservados.</p>';
 if(action==='revoke')fields='<p>A liberação gratuita termina agora. Voltam a valer o plano contratado e os controles normais de uso.</p>';
 openDialog(({edit:'Editar cadastro',grant:'Liberar acesso',suspend:'Inativar empresa',activate:'Reativar empresa',delete:'Excluir do diretório',revoke:'Encerrar liberação'})[action],`<form id="client-form" data-action="${action}">${fields}${input('reason','Motivo da alteração')}<p id="client-error" role="alert"></p><button class="p-button primary">Confirmar alteração</button></form>`);
 }
 document.addEventListener('click',async e=>{if(!active)return;const tab=e.target.closest('[data-client-tab]');if(tab)return detail(tab.dataset.clientTab);const b=e.target.closest('[data-client-action]');if(!b)return;b.disabled=true;try{if(b.dataset.clientAction==='open')await open(b.dataset.id);else{if(selected?.company.id!==b.dataset.id)await open(b.dataset.id);form(b.dataset.clientAction);}}catch(err){toast(err.message,true);}finally{b.disabled=false;}});
 document.addEventListener('input',e=>{if(active&&e.target.id==='client-search'){const pos=e.target.selectionStart;search=e.target.value.toLocaleLowerCase('pt-BR');paint();const f=document.querySelector('#client-search');f.focus();f.setSelectionRange(pos,pos);}});
 document.addEventListener('change',e=>{if(active&&e.target.id==='client-state'){state=e.target.value;paint();}});
 document.addEventListener('submit',async e=>{if(!active||e.target.id!=='client-form')return;e.preventDefault();const f=e.target,b=f.querySelector('button'),d=Object.fromEntries(new FormData(f)),id=selected.company.id,version=selected.control.version;b.disabled=true;try{selected=await api(endpoint(id),'POST',{...d,action:f.dataset.action,version,confirmed:d.confirmed==='on',end:d.end?d.end+'T23:59:59-03:00':null});await load();if(active){detail(f.dataset.action==='grant'?'access':'summary');toast('Cadastro atualizado.');}}catch(err){f.querySelector('#client-error').textContent=err.message;}finally{b.disabled=false;}});
 return {page,mount(v){active=v==='clients';++epoch;if(active)load();}};
}
